# Week 8: Solutions

## Exercise 1: Token Budget

```python
@dataclass
class TokenBudget:
    max_tokens: int
    tokens_used: int = 0

    def check(self, tokens: int) -> bool:
        return self.tokens_used + tokens <= self.max_tokens

    def consume(self, tokens: int):
        if not self.check(tokens):
            raise ValueError(f"Token budget exceeded: {self.tokens_used + tokens} > {self.max_tokens}")
        self.tokens_used += tokens

    def remaining(self) -> int:
        return self.max_tokens - self.tokens_used
```

## Exercise 2: Time Budget

```python
@dataclass
class TimeBudget:
    max_seconds: float
    start_time: float = None

    def __post_init__(self):
        if self.start_time is None:
            self.start_time = time.time()

    def elapsed(self) -> float:
        return time.time() - self.start_time

    def remaining(self) -> float:
        return self.max_seconds - self.elapsed()

    def is_exceeded(self) -> bool:
        return self.elapsed() > self.max_seconds
```

## Exercise 3: Cost Budget

```python
@dataclass
class CostBudget:
    max_cost_usd: float
    cost_used_usd: float = 0.0

    def charge(self, cost: float):
        if not self.can_afford(cost):
            raise ValueError(f"Cost budget exceeded: {self.cost_used_usd + cost} > {self.max_cost_usd}")
        self.cost_used_usd += cost

    def can_afford(self, cost: float) -> bool:
        return self.cost_used_usd + cost <= self.max_cost_usd

    def remaining(self) -> float:
        return self.max_cost_usd - self.cost_used_usd
```

## Exercise 4: Combined Budget

```python
@dataclass
class Budget:
    max_tokens: Optional[int] = None
    max_seconds: Optional[float] = None
    max_cost_usd: Optional[float] = None

    tokens_used: int = 0
    cost_used_usd: float = 0.0
    start_time: float = None

    def __post_init__(self):
        if self.start_time is None:
            self.start_time = time.time()

    def check(self) -> bool:
        if self.max_tokens and self.tokens_used > self.max_tokens:
            return False
        if self.max_seconds and (time.time() - self.start_time) > self.max_seconds:
            return False
        if self.max_cost_usd and self.cost_used_usd > self.max_cost_usd:
            return False
        return True

    def charge_operation(self, tokens: int, cost: float):
        self.tokens_used += tokens
        self.cost_used_usd += cost

    def report(self) -> str:
        elapsed = time.time() - self.start_time
        lines = ["Budget Usage:"]
        if self.max_tokens:
            lines.append(f"  Tokens: {self.tokens_used}/{self.max_tokens}")
        if self.max_seconds:
            lines.append(f"  Time: {elapsed:.1f}s/{self.max_seconds}s")
        if self.max_cost_usd:
            lines.append(f"  Cost: ${self.cost_used_usd:.2f}/${self.max_cost_usd:.2f}")
        return "\n".join(lines)
```

