## Exercise 7: Parallel with Timeout

```python
async def run_parallel_with_timeout(
    tasks: List[Callable],
    timeout_seconds: float
) -> List[Optional[Any]]:
    """Run tasks in parallel with timeout."""
    async def task_with_timeout(task_fn):
        try:
            return await asyncio.wait_for(task_fn(), timeout=timeout_seconds)
        except asyncio.TimeoutError:
            return None

    return await asyncio.gather(*[task_with_timeout(t) for t in tasks])
```

## Exercise 8: Checkpointing

```python
class CheckpointManager:
    def __init__(self, checkpoint_file="checkpoint.json"):
        self.checkpoint_file = checkpoint_file
        self.checkpoints = {}
        self.load()

    def load(self):
        try:
            with open(self.checkpoint_file) as f:
                self.checkpoints = json.load(f)
        except FileNotFoundError:
            self.checkpoints = {}

    def save(self):
        import tempfile
        dir_name = os.path.dirname(self.checkpoint_file) or "."
        fd, temp_path = tempfile.mkstemp(dir=dir_name, suffix=".tmp")
        try:
            with os.fdopen(fd, "w") as f:
                json.dump(self.checkpoints, f, indent=2)
            os.rename(temp_path, self.checkpoint_file)
        except Exception:
            if os.path.exists(temp_path):
                os.unlink(temp_path)
            raise

    def checkpoint(self, name: str, data: Any):
        self.checkpoints[name] = data
        self.save()

    def get(self, name: str) -> Any:
        return self.checkpoints.get(name)

    def exists(self, name: str) -> bool:
        return name in self.checkpoints
```

## Exercise 9: Resumable Pipeline

```python
class ResumablePipeline:
    def __init__(self, steps: List[tuple], checkpoint_file="pipeline.json"):
        self.steps = steps
        self.checkpoint_mgr = CheckpointManager(checkpoint_file)

    def execute(self, initial_input: Any) -> Any:
        result = initial_input

        for name, step_func in self.steps:
            if self.checkpoint_mgr.exists(name):
                result = self.checkpoint_mgr.get(name)
                print(f"Skipping {name} (checkpoint found)")
            else:
                result = step_func(result)
                self.checkpoint_mgr.checkpoint(name, result)
                print(f"Executed {name}")

        return result
```

