            os.rename(temp_path, self.checkpoint_file)
        except Exception:
            if os.path.exists(temp_path):
                os.unlink(temp_path)
            raise

    def checkpoint(self, name: str, data: Any):
        self.checkpoints[name] = data
        self.save()
        print(f"Checkpoint saved: {name}")

    def get(self, name: str) -> Any:
        return self.checkpoints.get(name)

    def exists(self, name: str) -> bool:
        return name in self.checkpoints

class ResearchAssistant:
    def __init__(self, budget: Budget, checkpoint_file="research_checkpoint.json"):
        self.budget = budget
        self.checkpoint_mgr = CheckpointManager(checkpoint_file)

    async def search_web(self, query: str) -> Dict:
        """Simulate web search."""
        print("  - Web search: starting...")
        await asyncio.sleep(3)
        print("  - Web search: completed")
        return {
            "source": "web",
            "results": [f"Web result for '{query}'"],
            "tokens": 100
        }

    async def search_docs(self, query: str) -> Dict:
        """Simulate doc search."""
        print("  - Docs search: starting...")
        await asyncio.sleep(2)
        print("  - Docs search: completed")
        return {
            "source": "docs",
            "results": [f"Doc result for '{query}'"],
            "tokens": 150
        }

    async def search_papers(self, query: str) -> Dict:
        """Simulate academic search."""
        print("  - Papers search: starting...")
        await asyncio.sleep(4)
        print("  - Papers search: completed")
        return {
            "source": "papers",
            "results": [f"Paper result for '{query}'"],
            "tokens": 200
        }

    async def parallel_search(self, query: str) -> List[Dict]:
        """Run all searches in parallel with timeout."""
        print("\nSearching in parallel...")

        tasks = [
            self.search_web(query),
            self.search_docs(query),
            self.search_papers(query)
        ]

        results = []
        try:
            results = await asyncio.gather(*tasks, return_exceptions=True)
            # Filter out exceptions
            results = [r for r in results if not isinstance(r, Exception)]
        except Exception as e:
            print(f"Search error: {e}")

        return results

    def aggregate_results(self, search_results: List[Dict]) -> Dict:
        """Aggregate results from parallel searches."""
        print("\nAggregating results...")

        all_results = []
        total_tokens = 0

        for result in search_results:
            all_results.extend(result["results"])
            total_tokens += result["tokens"]

        self.budget.charge_tokens(total_tokens)

        return {
            "results": all_results,
            "sources": len(search_results),
            "tokens": total_tokens
        }

    def summarize(self, aggregated: Dict) -> str:
        """Summarize aggregated results."""
        print("\nSummarizing...")

        summary = f"Based on {aggregated['sources']} sources: "
        summary += ", ".join(aggregated['results'][:3])

        summary_tokens = 200
        self.budget.charge_tokens(summary_tokens)

        return summary

    async def research(self, question: str) -> str:
        """Execute full research workflow with checkpointing."""

        # Step 1: Parallel search
        if self.checkpoint_mgr.exists("search_results"):
            print("Loading search results from checkpoint...")
            search_results = self.checkpoint_mgr.get("search_results")
        else:
            if not self.budget.check():
                raise Exception("Budget exceeded before search")

            search_results = await self.parallel_search(question)
            self.checkpoint_mgr.checkpoint("search_results", search_results)

        # Step 2: Aggregate
        if self.checkpoint_mgr.exists("aggregated"):
            print("Loading aggregated results from checkpoint...")
            aggregated = self.checkpoint_mgr.get("aggregated")
        else:
            if not self.budget.check():
                raise Exception("Budget exceeded before aggregation")

            aggregated = self.aggregate_results(search_results)
            self.checkpoint_mgr.checkpoint("aggregated", aggregated)

        # Step 3: Summarize
        if not self.budget.check():
            raise Exception("Budget exceeded before summarization")

        summary = self.summarize(aggregated)

        return summary

if __name__ == "__main__":
    budget = Budget(max_tokens=5000, max_seconds=60.0)
    assistant = ResearchAssistant(budget)

    question = "What is agentic AI?"

    async def main():
        try:
            answer = await assistant.research(question)
            print(f"\nAnswer: {answer}\n")
            print(f"Budget used: {budget.tokens_used}/{budget.max_tokens} tokens")
            elapsed = time.time() - budget.start_time
            print(f"Time used: {elapsed:.1f}/{budget.max_seconds}s")

            if not budget.check():
                print("WARNING: Budget exceeded!")
        except Exception as e:
            print(f"\nResearch failed: {e}")
            elapsed = time.time() - budget.start_time
            print(f"Budget at failure: {budget.tokens_used}/{budget.max_tokens} tokens, {elapsed:.1f}s")

    asyncio.run(main())
```

This solution demonstrates production workflow orchestration: parallel execution, budgets, checkpointing, and graceful degradation.

