## Exercise 1: Basic Memory Store

```python
import json
import os
import tempfile
from datetime import datetime, timedelta
from typing import Dict, List, Optional, Any

class MemoryStore:
    def __init__(self, storage_file="memory.json"):
        self.storage_file = storage_file
        self.memory = {}
        self.load()

    def load(self):
        """Load memory from disk."""
        try:
            with open(self.storage_file) as f:
                self.memory = json.load(f)
        except FileNotFoundError:
            self.memory = {}
        except json.JSONDecodeError:
            print("Warning: Corrupted memory file, starting fresh")
            self.memory = {}

    def save(self):
        """Save memory to disk atomically."""
        dir_name = os.path.dirname(self.storage_file) or "."
        fd, temp_path = tempfile.mkstemp(dir=dir_name, suffix=".tmp")
        try:
            with os.fdopen(fd, "w") as f:
                json.dump(self.memory, f, indent=2)
            os.rename(temp_path, self.storage_file)
        except Exception:
            if os.path.exists(temp_path):
                os.unlink(temp_path)
            raise

    def store(self, namespace: str, key: str, value: Any, ttl_seconds: Optional[int] = None):
        """Store a value with optional TTL."""
        if namespace not in self.memory:
            self.memory[namespace] = {}

        entry = {
            "value": value,
            "created_at": datetime.now().isoformat(),
        }

        if ttl_seconds:
            expires_at = datetime.now() + timedelta(seconds=ttl_seconds)
            entry["expires_at"] = expires_at.isoformat()

        self.memory[namespace][key] = entry
        self.save()

    def retrieve(self, namespace: str, key: str) -> Optional[Any]:
        """Retrieve a value, return None if expired or missing."""
        if namespace not in self.memory or key not in self.memory[namespace]:
            return None

        entry = self.memory[namespace][key]

        # Check expiry
        if "expires_at" in entry:
            expires_at = datetime.fromisoformat(entry["expires_at"])
            if datetime.now() > expires_at:
                return None

        return entry["value"]

    def evict_expired(self):
        """Remove all expired entries."""
        now = datetime.now()
        for namespace in list(self.memory.keys()):
            for key in list(self.memory[namespace].keys()):
                entry = self.memory[namespace][key]
                if "expires_at" in entry:
                    expires_at = datetime.fromisoformat(entry["expires_at"])
                    if now > expires_at:
                        del self.memory[namespace][key]

            # Remove empty namespaces
            if not self.memory[namespace]:
                del self.memory[namespace]

        self.save()
```

## Exercise 2: Memory Search

```python
def search(self, namespace: str, query: str) -> List[Dict]:
    """Search for keys/values matching query string."""
    if namespace not in self.memory:
        return []

    query_lower = query.lower()
    results = []

    for key, entry in self.memory[namespace].items():
        # Skip expired
        if "expires_at" in entry:
            expires_at = datetime.fromisoformat(entry["expires_at"])
            if datetime.now() > expires_at:
                continue

        value_str = str(entry["value"]).lower()
        key_lower = key.lower()

        # Calculate relevance score (word matches)
        query_words = query_lower.split()
        score = 0
        for word in query_words:
            if word in value_str:
                score += 2
            if word in key_lower:
                score += 3

        if score > 0:
            results.append({
                "key": key,
                "value": entry["value"],
                "score": score
            })

    # Sort by score descending
    results.sort(key=lambda x: x["score"], reverse=True)
    return results
```

## Exercise 3: Token Counting & Truncation

```python
def count_tokens(text: str) -> int:
    """Approximate token count (1 token ≈ 4 chars)."""
    return len(text) // 4

def truncate_history(messages: List[str], max_tokens: int) -> List[str]:
    """Truncate message history to fit within max_tokens."""
    total_tokens = sum(count_tokens(msg) for msg in messages)

    if total_tokens <= max_tokens:
        return messages

    # Keep most recent messages
    truncated = []
    current_tokens = 0

    for msg in reversed(messages):
        msg_tokens = count_tokens(msg)
        if current_tokens + msg_tokens > max_tokens:
            break
        truncated.insert(0, msg)
        current_tokens += msg_tokens

    return truncated
```

## Exercise 4: Summarization

```python
def summarize_messages(messages: List[str]) -> str:
    """Extractive summarization: first + last sentences."""
    if len(messages) <= 2:
        return " ".join(messages)

    summary_parts = [
        messages[0],
        messages[1],
        "...",
        messages[-2],
        messages[-1]
    ]
    return " ".join(summary_parts)

def compress_history(messages: List[str], max_tokens: int) -> List[str]:
    """Compress history by summarizing old messages."""
    total_tokens = sum(count_tokens(msg) for msg in messages)

    if total_tokens <= max_tokens:
        return messages

    # Split in half
    mid = len(messages) // 2
    old_half = messages[:mid]
    recent_half = messages[mid:]

    # Summarize old half
    summary = summarize_messages(old_half)

    # Recursively compress if still too large
    compressed = [summary] + recent_half
    if sum(count_tokens(msg) for msg in compressed) > max_tokens:
        return compress_history(compressed, max_tokens)

    return compressed
```

## Exercise 5: Bounded Memory

```python
class BoundedMemoryStore(MemoryStore):
    def __init__(self, storage_file="memory.json", max_entries=100):
        self.max_entries = max_entries
        super().__init__(storage_file)

    def store(self, namespace: str, key: str, value: Any, ttl_seconds: Optional[int] = None):
        """Store value, evict oldest if over limit."""
        # Store first
        super().store(namespace, key, value, ttl_seconds)

        # Check limit
        if self.count_entries() > self.max_entries:
            self.evict_oldest()

    def count_entries(self) -> int:
        """Count total entries."""
        total = 0
        for namespace in self.memory.values():
            total += len(namespace)
        return total

    def evict_oldest(self, count=1):
        """Evict the oldest N entries by creation time."""
        all_entries = []

        for namespace_name, namespace in self.memory.items():
            for key, entry in namespace.items():
                all_entries.append((namespace_name, key, entry))

        # Sort by created_at
        all_entries.sort(key=lambda x: x[2].get("created_at", ""))

        # Remove oldest
        for i in range(min(count, len(all_entries))):
            namespace_name, key, _ = all_entries[i]
            del self.memory[namespace_name][key]

        self.save()
```

