## Mini-Project Solution

```python
import json
import os
import tempfile
import re
from datetime import datetime
from typing import Dict, List, Optional

class NoteMemory:
    def __init__(self, storage_file="notes_memory.json", max_facts=50):
        self.storage_file = storage_file
        self.max_facts = max_facts
        self.facts = {}
        self.conversation_history = []
        self.load()

    def load(self):
        try:
            with open(self.storage_file) as f:
                data = json.load(f)
                self.facts = data.get("facts", {})
                self.conversation_history = data.get("history", [])
        except (FileNotFoundError, json.JSONDecodeError):
            self.facts = {}
            self.conversation_history = []

    def save(self):
        data = {
            "facts": self.facts,
            "history": self.conversation_history
        }
        dir_name = os.path.dirname(self.storage_file) or "."
        fd, temp_path = tempfile.mkstemp(dir=dir_name, suffix=".tmp")
        try:
            with os.fdopen(fd, "w") as f:
                json.dump(data, f, indent=2)
            os.rename(temp_path, self.storage_file)
        except Exception:
            if os.path.exists(temp_path):
                os.unlink(temp_path)
            raise

    def store_fact(self, key: str, value: str, ttl_seconds: Optional[int] = None):
        """Store a fact with optional TTL (time-to-live) in seconds."""
        entry = {
            "value": value,
            "created_at": datetime.now().isoformat()
        }

        # Add expiry time if TTL specified
        if ttl_seconds is not None:
            from datetime import timedelta
            expires_at = datetime.now() + timedelta(seconds=ttl_seconds)
            entry["expires_at"] = expires_at.isoformat()

        self.facts[key] = entry

        # Evict oldest if over limit
        if len(self.facts) > self.max_facts:
            sorted_facts = sorted(
                self.facts.items(),
                key=lambda x: x[1]["created_at"]
            )
            oldest_key = sorted_facts[0][0]
            del self.facts[oldest_key]

        self.save()

    def search_facts(self, query: str) -> List[Dict]:
        """Search facts, automatically skipping expired entries."""
        query_lower = query.lower()
        results = []
        now = datetime.now()

        for key, fact in self.facts.items():
            # Skip expired entries
            if "expires_at" in fact:
                expires_at = datetime.fromisoformat(fact["expires_at"])
                if now > expires_at:
                    continue

            value_str = fact["value"].lower()
            score = 0

            for word in query_lower.split():
                if word in value_str:
                    score += 2
                if word in key.lower():
                    score += 3

            if score > 0:
                results.append({
                    "key": key,
                    "value": fact["value"],
                    "score": score
                })

        results.sort(key=lambda x: x["score"], reverse=True)
        return results

    def add_message(self, role: str, content: str):
        self.conversation_history.append({
            "role": role,
            "content": content,
            "timestamp": datetime.now().isoformat()
        })
        self.save()

    def clear_expired(self):
        """Remove all expired facts from storage."""
        now = datetime.now()
        expired_keys = []

        for key, fact in self.facts.items():
            if "expires_at" in fact:
                expires_at = datetime.fromisoformat(fact["expires_at"])
                if now > expires_at:
                    expired_keys.append(key)

        for key in expired_keys:
            del self.facts[key]

        if expired_keys:
            self.save()

        return len(expired_keys)

    def get_context(self, max_tokens=2000) -> List[Dict]:
        total_tokens = sum(len(msg["content"]) // 4 for msg in self.conversation_history)

        if total_tokens <= max_tokens:
            return self.conversation_history

        # Keep recent messages
        context = []
        current_tokens = 0

        for msg in reversed(self.conversation_history):
            msg_tokens = len(msg["content"]) // 4
            if current_tokens + msg_tokens > max_tokens:
                break
            context.insert(0, msg)
            current_tokens += msg_tokens

        return context

class NoteAssistant:
    def __init__(self, memory: NoteMemory):
        self.memory = memory

    def process_command(self, user_input: str) -> str:
        self.memory.add_message("user", user_input)

        # Parse command
        lower_input = user_input.lower()

        if lower_input.startswith("remember that "):
            # Check for TTL syntax: "remember that X (expires in N seconds)"
            ttl_match = re.search(r'\(expires in (\d+) seconds?\)', user_input, re.IGNORECASE)
            ttl_seconds = None
            if ttl_match:
                ttl_seconds = int(ttl_match.group(1))
                # Remove TTL part from input for fact extraction
                user_input = re.sub(r'\s*\(expires in \d+ seconds?\)', '', user_input, flags=re.IGNORECASE)

            fact = self.extract_fact(user_input)
            if fact:
                key, value = fact
                self.memory.store_fact(key, value, ttl_seconds=ttl_seconds)
                if ttl_seconds:
                    response = f"Noted! Stored under \"{key}\" (expires in {ttl_seconds}s)"
                else:
                    response = f"Noted! Stored under \"{key}\""
            else:
                response = "I couldn't parse that. Try: 'remember that X' or 'remember that X (expires in N seconds)'"

        elif "what do you know about" in lower_input:
            query = re.sub(r"what do you know about\s+", "", lower_input, flags=re.IGNORECASE)
            query = query.rstrip("?")
            results = self.memory.search_facts(query)

            if results:
                response = f"I found {len(results)} note(s) about {query}:\n"
                for r in results[:3]:
                    response += f"- {r['key']}: {r['value']}\n"
            else:
                response = f"I don't have any notes about {query}"

        elif lower_input == "list all notes":
            if self.memory.facts:
                response = f"I have {len(self.memory.facts)} notes:\n"
                for i, (key, fact) in enumerate(self.memory.facts.items(), 1):
                    response += f"{i}. {key}: {fact['value']}\n"
            else:
                response = "I don't have any notes yet"

        elif lower_input == "summarize":
            context = self.memory.get_context()
            response = f"Conversation has {len(context)} messages in context"

        elif lower_input == "clear expired":
            count = self.memory.clear_expired()
            response = f"Cleared {count} expired note(s)"

        else:
            response = "Commands: 'remember that X', 'what do you know about X', 'list all notes', 'clear expired'"

        self.memory.add_message("assistant", response)
        return response

    def extract_fact(self, text: str) -> Optional[tuple]:
        match = re.match(r"remember that\s+(.+)", text, re.IGNORECASE)
        if not match:
            return None

        fact_text = match.group(1)
        words = fact_text.split()

        if len(words) < 2:
            return None

        # Use first word as key
        key = words[0].lower().strip(".,!?")
        value = fact_text

        return (key, value)

if __name__ == "__main__":
    memory = NoteMemory()
    assistant = NoteAssistant(memory)

    print("Note-Taking Assistant (type 'quit' to exit)")
    print("Commands:")
    print("  - 'remember that X' - Store a fact")
    print("  - 'remember that X (expires in N seconds)' - Store a fact with TTL")
    print("  - 'what do you know about X' - Search for facts")
    print("  - 'list all notes' - List all stored facts")
    print("  - 'clear expired' - Remove expired facts\n")

    while True:
        user_input = input("You: ").strip()
        if user_input.lower() == "quit":
            break

        if not user_input:
            continue

        response = assistant.process_command(user_input)
        print(f"Assistant: {response}\n")
```

This solution demonstrates all memory patterns from Week 6: storage, retrieval, search, context management, and persistence.

