## Exercise 5 Solution: Tool Input Validation

```python
from typing import get_type_hints, Any, Dict, Callable, Optional
import inspect
from dataclasses import dataclass

_REGISTRY: Dict[str, Callable] = {}

@dataclass
class ToolResult:
    success: bool
    value: Optional[Any] = None
    error: Optional[str] = None

class ValidationError(Exception):
    """Raised when tool input validation fails."""
    pass

def tool(func: Optional[Callable] = None, *, name: Optional[str] = None):
    """Register a function as a tool."""
    def decorator(f: Callable) -> Callable:
        tool_name = name if name else f.__name__
        _REGISTRY[tool_name] = f
        return f

    if func is not None:
        return decorator(func)
    return decorator

def validate_input(func: Callable, kwargs: Dict[str, Any]) -> None:
    """Validate inputs against function signature and type hints.

    Args:
        func: The function to validate against
        kwargs: The keyword arguments to validate

    Raises:
        ValidationError: If validation fails
    """
    sig = inspect.signature(func)
    type_hints = get_type_hints(func)

    # Check for required parameters
    for param_name, param in sig.parameters.items():
        # Skip if parameter has default value
        if param.default != inspect.Parameter.empty:
            continue

        # Check if required parameter is missing
        if param_name not in kwargs:
            raise ValidationError(
                f"Missing required parameter: '{param_name}'"
            )

    # Check types for provided parameters
    for param_name, value in kwargs.items():
        if param_name not in sig.parameters:
            raise ValidationError(
                f"Unknown parameter: '{param_name}'"
            )

        expected_type = type_hints.get(param_name)
        if expected_type is None:
            continue  # No type hint, skip validation

        # Handle special case: int is acceptable for float
        actual_type = type(value)
        if expected_type == float and actual_type == int:
            continue

        # Basic type checking
        if not isinstance(value, expected_type):
            raise ValidationError(
                f"Parameter '{param_name}': expected {expected_type.__name__}, "
                f"got {actual_type.__name__}"
            )

def call_tool(name: str, **kwargs) -> ToolResult:
    """Call a tool with input validation.

    Args:
        name: Name of tool to call
        **kwargs: Arguments to pass to tool

    Returns:
        ToolResult with success status and value or error
    """
    if name not in _REGISTRY:
        return ToolResult(
            success=False,
            error=f"Tool '{name}' not found"
        )

    tool_func = _REGISTRY[name]

    try:
        # Validate inputs
        validate_input(tool_func, kwargs)

        # Execute tool
        result = tool_func(**kwargs)
        return ToolResult(success=True, value=result)

    except ValidationError as e:
        return ToolResult(success=False, error=f"Validation error: {str(e)}")
    except Exception as e:
        return ToolResult(success=False, error=f"{type(e).__name__}: {str(e)}")

# Register tools
@tool()
def divide(a: int, b: int) -> float:
    """Divide a by b."""
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

@tool()
def greet(name: str, title: str = "Mr.") -> str:
    """Greet someone with optional title."""
    return f"Hello, {title} {name}!"

# Usage
if __name__ == "__main__":
    # Valid call
    result = call_tool("divide", a=10, b=5)
    print(f"1. Success: {result.success}, Value: {result.value}")

    # Type error
    result = call_tool("divide", a=10, b="5")
    print(f"2. Success: {result.success}, Error: {result.error}")

    # Missing required parameter
    result = call_tool("divide", a=10)
    print(f"3. Success: {result.success}, Error: {result.error}")

    # Optional parameter omitted (should work)
    result = call_tool("greet", name="Alice")
    print(f"4. Success: {result.success}, Value: {result.value}")

    # Optional parameter provided
    result = call_tool("greet", name="Bob", title="Dr.")
    print(f"5. Success: {result.success}, Value: {result.value}")

    # Unknown parameter
    result = call_tool("greet", name="Charlie", age=30)
    print(f"6. Success: {result.success}, Error: {result.error}")
```

## Mini-Project Solution: Calculator Agent

```python
import time
import json
import logging
import sys
from typing import Dict, Callable, Any, Optional, List, Tuple, get_type_hints
from dataclasses import dataclass, asdict
import inspect

# ============================================================================
# Logging Setup
# ============================================================================

class JSONFormatter(logging.Formatter):
    """Format log records as JSON."""
    def format(self, record: logging.LogRecord) -> str:
        log_obj = {"level": record.levelname}
        for key, value in record.__dict__.items():
            if key not in ("name", "msg", "args", "created", "filename", "funcName",
                          "levelname", "levelno", "lineno", "module", "msecs",
                          "message", "pathname", "process", "processName",
                          "relativeCreated", "thread", "threadName", "exc_info",
                          "exc_text", "stack_info"):
                log_obj[key] = value
        if hasattr(record, 'event'):
            log_obj["message"] = record.getMessage() if record.getMessage() else None
            if log_obj["message"] is None:
                del log_obj["message"]
        else:
            log_obj["message"] = record.getMessage()
        return json.dumps(log_obj)

logger = logging.getLogger("calculator")
logger.setLevel(logging.INFO)
handler = logging.StreamHandler(sys.stdout)
handler.setFormatter(JSONFormatter())
logger.addHandler(handler)
logger.propagate = False

# ============================================================================
# Data Models
# ============================================================================

@dataclass
class ToolMetadata:
    name: str
    description: str
    parameters: Dict[str, Any]
    return_type: Any

@dataclass
class ToolResult:
    success: bool
    tool_name: str
    value: Optional[float] = None
    error: Optional[str] = None
    execution_time: Optional[float] = None

# ============================================================================
# Exceptions
# ============================================================================

class ValidationError(Exception):
    """Raised when input validation fails."""
    pass

class UnknownToolError(Exception):
    """Raised when tool is not found."""
    pass

# ============================================================================
# Tool Registry
# ============================================================================

_REGISTRY: Dict[str, Callable] = {}
_METADATA: Dict[str, ToolMetadata] = {}

def tool(func: Optional[Callable] = None, *, name: Optional[str] = None,
         description: str = ""):
    """Register a function as a tool."""
    def decorator(f: Callable) -> Callable:
        tool_name = name if name else f.__name__

        # Prevent duplicates
        if tool_name in _REGISTRY:
            raise ValueError(f"Tool '{tool_name}' already registered")

        # Extract metadata
        sig = inspect.signature(f)
        type_hints = get_type_hints(f)
        parameters = {pname: type_hints.get(pname, Any)
                     for pname in sig.parameters.keys()}
        return_type = type_hints.get('return', Any)

        # Register
        _REGISTRY[tool_name] = f
        _METADATA[tool_name] = ToolMetadata(
            name=tool_name,
            description=description or f.__doc__ or "",
            parameters=parameters,
            return_type=return_type
        )

        logger.info("", extra={
            "event": "tool_registered",
            "tool_name": tool_name,
            "parameters": list(parameters.keys())
        })

        return f

    if func is not None:
        return decorator(func)
    return decorator

def get_tool_metadata(name: str) -> ToolMetadata:
    """Get metadata for a tool."""
    if name not in _METADATA:
        raise UnknownToolError(f"Tool '{name}' not found")
    return _METADATA[name]

def list_tools() -> List[str]:
    """List all registered tool names."""
    return sorted(_REGISTRY.keys())

def list_tools_with_metadata() -> List[ToolMetadata]:
    """List all tools with metadata."""
    return [_METADATA[name] for name in sorted(_METADATA.keys())]

# ============================================================================
# Input Validation
# ============================================================================

def validate_input(func: Callable, kwargs: Dict[str, Any]) -> None:
    """Validate inputs against function signature."""
    sig = inspect.signature(func)
    type_hints = get_type_hints(func)

    # Check required parameters
    for param_name, param in sig.parameters.items():
        if param.default == inspect.Parameter.empty and param_name not in kwargs:
            raise ValidationError(f"Missing required parameter: '{param_name}'")

    # Check types
    for param_name, value in kwargs.items():
        if param_name not in sig.parameters:
            raise ValidationError(f"Unknown parameter: '{param_name}'")

        expected_type = type_hints.get(param_name)
        if expected_type is None:
            continue

        actual_type = type(value)
        # Allow int for float
        if expected_type == float and actual_type in (int, float):
            continue
        if expected_type == int and actual_type == int:
            continue

        if not isinstance(value, expected_type):
            raise ValidationError(
                f"Parameter '{param_name}': expected {expected_type.__name__}, "
                f"got {actual_type.__name__}"
            )

# ============================================================================
# Tool Execution
# ============================================================================

def call_tool(name: str, **kwargs) -> ToolResult:
    """Execute a tool by name."""
    start_time = time.time()

    logger.info("", extra={
        "event": "tool_execution_attempt",
        "tool_name": name,
        "inputs": kwargs
    })

    # Check if tool exists
    if name not in _REGISTRY:
        error_msg = f"Tool '{name}' not found. Available: {', '.join(list_tools())}"
        logger.error("", extra={
            "event": "tool_not_found",
            "tool_name": name,
            "available_tools": list_tools()
        })
        return ToolResult(success=False, tool_name=name, error=error_msg)

    tool_func = _REGISTRY[name]

    try:
        # Validate inputs
        validate_input(tool_func, kwargs)

        # Execute
        result = tool_func(**kwargs)
        execution_time = time.time() - start_time

        logger.info("", extra={
            "event": "tool_execution_success",
            "tool_name": name,
            "result": result,
            "execution_time": round(execution_time, 6)
        })

        return ToolResult(
            success=True,
            tool_name=name,
            value=result,
            execution_time=execution_time
        )

    except Exception as e:
        execution_time = time.time() - start_time
        error_msg = f"{type(e).__name__}: {str(e)}"

        logger.error("", extra={
            "event": "tool_execution_failed",
            "tool_name": name,
            "error": error_msg,
            "error_type": type(e).__name__
        })

        return ToolResult(
            success=False,
            tool_name=name,
            error=error_msg,
            execution_time=execution_time
        )

# ============================================================================
# Calculator Tools
# ============================================================================

@tool(description="Add two numbers")
def add(a: float, b: float) -> float:
    return a + b

@tool(description="Subtract b from a")
def subtract(a: float, b: float) -> float:
    return a - b

@tool(description="Multiply two numbers")
def multiply(a: float, b: float) -> float:
    return a * b

@tool(description="Divide a by b")
def divide(a: float, b: float) -> float:
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

@tool(description="Raise base to exponent")
def power(base: float, exponent: float) -> float:
    return base ** exponent

@tool(description="Calculate square root")
def sqrt(x: float) -> float:
    if x < 0:
        raise ValueError("Cannot take square root of negative number")
    return x ** 0.5

# ============================================================================
# REPL
# ============================================================================

def print_help():
    """Print available tools."""
    print("\nAvailable tools:")
    for metadata in list_tools_with_metadata():
        params = ", ".join(metadata.parameters.keys())
        print(f"  {metadata.name}({params}) - {metadata.description}")
    print()

def parse_command(line: str) -> Tuple[str, Dict[str, float]]:
    """Parse a command line into tool name and arguments."""
    parts = line.strip().split()
    if not parts:
        raise ValueError("Empty command")

    tool_name = parts[0]
    args = [float(x) for x in parts[1:]]

    # Get parameter names from metadata
    metadata = get_tool_metadata(tool_name)
    param_names = list(metadata.parameters.keys())

    if len(args) != len(param_names):
        raise ValueError(
            f"{tool_name} expects {len(param_names)} arguments ({', '.join(param_names)}), "
            f"got {len(args)}"
        )

    return tool_name, dict(zip(param_names, args))

def repl():
    """Run the calculator REPL."""
    print("Calculator Agent v1.0")
    print("Type 'help' for available tools, 'quit' to exit\n")

    while True:
        try:
            line = input("> ").strip()

            if not line:
                continue

            if line == "quit":
                print("Goodbye!")
                break

            if line == "help":
                print_help()
                continue

            # Parse and execute
            tool_name, kwargs = parse_command(line)
            result = call_tool(tool_name, **kwargs)

            if result.success:
                print(f"Result: {result.value} (executed in {result.execution_time:.6f}s)")
            else:
                print(f"Error: {result.error}")

        except UnknownToolError as e:
            print(f"Error: {e}")
            print(f"Available tools: {', '.join(list_tools())}")
        except ValueError as e:
            print(f"Error: {e}")
        except KeyboardInterrupt:
            print("\nGoodbye!")
            break
        except EOFError:
            print("\nGoodbye!")
            break

# ============================================================================
# Main
# ============================================================================

if __name__ == "__main__":
    # Disable JSON logging for cleaner REPL output (optional)
    # Comment this out if you want to see JSON logs
    logger.disabled = True

    repl()
