from dataclasses import dataclass

def validate_email(email: str) -> None:
    """Validate email format."""
    if email.count('@') != 1:
        raise ValueError("Email must contain exactly one @")

    parts = email.split('@')
    if not parts[0] or not parts[1]:
        raise ValueError("Email must have text before and after @")

def validate_phone(phone: str) -> None:
    """Validate phone number (10 digits)."""
    # Remove dashes and spaces
    digits = phone.replace('-', '').replace(' ', '')

    if not digits.isdigit():
        raise ValueError("Phone must contain only digits, spaces, and dashes")

    if len(digits) != 10:
        raise ValueError(f"Phone must be 10 digits, got {len(digits)}")

def validate_range(value: float, min_val: float, max_val: float,
                  field_name: str) -> None:
    """Validate value is in range [min_val, max_val]."""
    if value < min_val or value > max_val:
        raise ValueError(
            f"Field '{field_name}' must be between {min_val} and {max_val}, got {value}"
        )

def validate_length(text: str, max_length: int, field_name: str) -> None:
    """Validate text length."""
    if len(text) > max_length:
        raise ValueError(
            f"Field '{field_name}' cannot exceed {max_length} characters, got {len(text)}"
