## Exercise 5 Solution: Sanitization and Rejection

```python
from dataclasses import dataclass, MISSING
from typing import Optional, Any, List, Tuple, get_type_hints
import re

@dataclass
class SanitizationResult:
    success: bool
    data: Optional[Any] = None
    errors: List[str] = None
    warnings: List[str] = None

    def __post_init__(self):
        if self.errors is None:
            self.errors = []
        if self.warnings is None:
            self.warnings = []

def sanitize_text(text: str, max_length: int) -> Tuple[str, List[str]]:
    """Sanitize text with whitespace normalization and truncation.

    Returns:
        Tuple of (sanitized_text, warnings)
    """
    warnings = []

    # Strip leading/trailing whitespace
    sanitized = text.strip()

    # Collapse multiple spaces to single space
    sanitized = re.sub(r'\s+', ' ', sanitized)

    # Truncate if needed
    if len(sanitized) > max_length:
        sanitized = sanitized[:max_length]
        warnings.append(f"Text truncated to {max_length} characters")

    return sanitized, warnings

def sanitize_and_validate(raw_data: dict, schema_class: type) -> SanitizationResult:
    """Sanitize raw data and validate against schema.

    Args:
        raw_data: Dictionary of raw input data
        schema_class: Dataclass schema to validate against

    Returns:
        SanitizationResult with success status, sanitized data, errors, warnings
    """
    errors = []
    warnings = []
    sanitized_data = {}

    # Get type hints from schema
    try:
        type_hints = get_type_hints(schema_class)
    except Exception as e:
        return SanitizationResult(
            success=False,
            errors=[f"Failed to get type hints: {e}"]
        )

    # Process each field in schema
    from dataclasses import fields
    for field in fields(schema_class):
        field_name = field.name
        expected_type = type_hints.get(field_name, Any)

        # Check if field is in raw data
        if field_name not in raw_data:
            # Check if field has default
            if field.default is not MISSING or field.default_factory is not MISSING:
                continue  # Will use default
            else:
                errors.append(f"Missing required field: '{field_name}'")
                continue

        value = raw_data[field_name]

        # Sanitize strings
        if expected_type == str and isinstance(value, str):
            # Apply generic sanitization (could be customized per field)
            sanitized, field_warnings = sanitize_text(value, max_length=1000)
            sanitized_data[field_name] = sanitized
            warnings.extend([f"{field_name}: {w}" for w in field_warnings])
            continue

        # Type coercion
        if not isinstance(value, expected_type):
            # Try to convert
            try:
                if expected_type == int:
                    converted = int(value)
                    sanitized_data[field_name] = converted
                    warnings.append(f"{field_name}: converted {type(value).__name__} to int")
                elif expected_type == float:
                    converted = float(value)
                    sanitized_data[field_name] = converted
                    warnings.append(f"{field_name}: converted {type(value).__name__} to float")
                elif expected_type == bool:
                    # Handle string booleans
                    if isinstance(value, str):
                        if value.lower() in ('true', '1', 'yes'):
                            sanitized_data[field_name] = True
                            warnings.append(f"{field_name}: converted string to bool")
                        elif value.lower() in ('false', '0', 'no'):
                            sanitized_data[field_name] = False
                            warnings.append(f"{field_name}: converted string to bool")
                        else:
                            errors.append(f"{field_name}: cannot convert '{value}' to bool")
                    else:
                        sanitized_data[field_name] = bool(value)
                        warnings.append(f"{field_name}: converted {type(value).__name__} to bool")
                else:
                    errors.append(
                        f"{field_name}: expected {expected_type.__name__}, "
                        f"got {type(value).__name__}, cannot convert"
                    )
            except (ValueError, TypeError) as e:
                errors.append(f"{field_name}: conversion failed: {e}")
        else:
            sanitized_data[field_name] = value

    # If there are errors, don't try to create instance
    if errors:
        return SanitizationResult(
            success=False,
            errors=errors,
            warnings=warnings
        )

    # Try to create schema instance (will run __post_init__ validation)
    try:
        instance = schema_class(**sanitized_data)
        return SanitizationResult(
            success=True,
            data=instance,
            warnings=warnings
        )
    except Exception as e:
        errors.append(f"Schema validation failed: {e}")
        return SanitizationResult(
            success=False,
            errors=errors,
            warnings=warnings
        )

# Test schema
@dataclass
class UserProfile:
    username: str
    age: int
    score: float
    active: bool

    def __post_init__(self):
        if self.age < 0:
            raise ValueError("age must be non-negative")
        if self.score < 0 or self.score > 100:
            raise ValueError("score must be between 0 and 100")

# Test cases
if __name__ == "__main__":
    # Clean data
    result = sanitize_and_validate(
        {"username": "alice", "age": 30, "score": 95.5, "active": True},
        UserProfile
    )
    print(f"1. Clean data: success={result.success}")
    print(f"   Data: {result.data}")
    print(f"   Warnings: {result.warnings}")

    # Messy strings
    result = sanitize_and_validate(
        {"username": "  bob  jones  ", "age": 25, "score": 88.0, "active": False},
        UserProfile
    )
    print(f"\n2. Messy string: success={result.success}")
    print(f"   Username: '{result.data.username}'")
    print(f"   Warnings: {result.warnings}")

    # Type coercion
    result = sanitize_and_validate(
        {"username": "charlie", "age": "35", "score": "72.5", "active": "true"},
        UserProfile
    )
    print(f"\n3. Type coercion: success={result.success}")
    print(f"   Data: {result.data}")
    print(f"   Warnings: {result.warnings}")

    # Missing required field
    result = sanitize_and_validate(
        {"username": "diana", "age": 28},
        UserProfile
    )
    print(f"\n4. Missing field: success={result.success}")
    print(f"   Errors: {result.errors}")

    # Invalid type (can't convert)
    result = sanitize_and_validate(
        {"username": "eve", "age": "not a number", "score": 90.0, "active": True},
        UserProfile
    )
    print(f"\n5. Invalid type: success={result.success}")
    print(f"   Errors: {result.errors}")

    # Schema validation failure
    result = sanitize_and_validate(
        {"username": "frank", "age": -5, "score": 85.0, "active": True},
