    )
    print(f"\n6. Schema validation: success={result.success}")
    print(f"   Errors: {result.errors}")

    # Out of range score
    result = sanitize_and_validate(
        {"username": "grace", "age": 40, "score": 150.0, "active": True},
        UserProfile
    )
    print(f"\n7. Out of range: success={result.success}")
    print(f"   Errors: {result.errors}")
