@dataclass
class PowerInput:
    base: float
    exponent: float

    def __post_init__(self):
        if self.base < 0 and not float(self.exponent).is_integer():
            raise ValueError("If base is negative, exponent must be an integer")

@dataclass
class SqrtInput:
    x: float

    def __post_init__(self):
        if self.x < 0:
            raise ValueError("Field 'x' must be non-negative")

# ============================================================================
# Output Schema
# ============================================================================

@dataclass
class ToolOutput:
    value: float
    metadata: Optional[dict] = None

    def __post_init__(self):
        if not isinstance(self.value, (int, float)):
            raise ValueError("value must be numeric")
        if self.metadata is not None and not isinstance(self.metadata, dict):
            raise ValueError("metadata must be dict or None")

# ============================================================================
# Tool Result
# ============================================================================

@dataclass
class ToolResult:
    success: bool
    tool_name: str
    value: Optional[float] = None
    error: Optional[str] = None
    execution_time: Optional[float] = None
    validation_errors: Optional[List[str]] = None
    validation_stage: Optional[str] = None

# ============================================================================
# Tool Registry
# ============================================================================

_REGISTRY: Dict[str, Callable] = {}
_INPUT_SCHEMAS: Dict[str, type] = {}
_METADATA: Dict[str, dict] = {}

def tool(input_schema: type, description: str = ""):
    """Register a tool with its input schema."""
    def decorator(func: Callable) -> Callable:
        tool_name = func.__name__

        if tool_name in _REGISTRY:
            raise ValueError(f"Tool '{tool_name}' already registered")

        _REGISTRY[tool_name] = func
        _INPUT_SCHEMAS[tool_name] = input_schema
        _METADATA[tool_name] = {"description": description}

        logger.info("", extra={
            "event": "tool_registered",
            "tool_name": tool_name,
            "input_schema": input_schema.__name__
        })

        return func
    return decorator

# ============================================================================
# Validation Functions
# ============================================================================

def validate_input(data: dict, schema_class: type) -> ValidationResult:
    """Validate input data against schema."""
    try:
        # Try to create instance (will run __post_init__ validation)
        instance = schema_class(**data)
        return ValidationResult(valid=True)
    except TypeError as e:
        # Missing or extra fields
        return ValidationResult(valid=False, errors=[f"Schema error: {e}"])
    except ValueError as e:
        # Validation error from __post_init__
        return ValidationResult(valid=False, errors=[str(e)])
    except Exception as e:
        return ValidationResult(valid=False, errors=[f"Validation failed: {e}"])

def validate_output(data: Any) -> ValidationResult:
    """Validate output is ToolOutput instance."""
    if not isinstance(data, ToolOutput):
        return ValidationResult(
            valid=False,
            errors=[f"Output must be ToolOutput instance, got {type(data).__name__}"]
        )

    try:
        # ToolOutput.__post_init__ already ran, but double-check
        if not isinstance(data.value, (int, float)):
            return ValidationResult(valid=False, errors=["value must be numeric"])
        return ValidationResult(valid=True)
    except Exception as e:
        return ValidationResult(valid=False, errors=[f"Output validation failed: {e}"])

# ============================================================================
# Tool Execution
# ============================================================================

def call_tool(name: str, input_data: dict) -> ToolResult:
    """Execute a tool with input and output validation."""
    start_time = time.time()

    logger.info("", extra={
        "event": "tool_execution_attempt",
        "tool_name": name,
        "inputs": input_data
    })

    # Check if tool exists
    if name not in _REGISTRY:
        return ToolResult(
            success=False,
            tool_name=name,
            error=f"Tool '{name}' not found",
            validation_stage="lookup"
        )

    # Get input schema
    input_schema = _INPUT_SCHEMAS[name]

    # Validate input
    input_validation = validate_input(input_data, input_schema)
    if not input_validation.valid:
        logger.error("", extra={
            "event": "input_validation_failed",
            "tool_name": name,
            "errors": input_validation.errors
        })
        return ToolResult(
            success=False,
            tool_name=name,
            error="; ".join(input_validation.errors),
            validation_errors=input_validation.errors,
            validation_stage="input"
        )

    # Create input instance
    try:
        input_instance = input_schema(**input_data)
    except Exception as e:
        return ToolResult(
            success=False,
            tool_name=name,
            error=f"Failed to create input: {e}",
            validation_stage="input"
        )

    # Execute tool
    tool_func = _REGISTRY[name]
    try:
        output = tool_func(input_instance)
    except Exception as e:
        execution_time = time.time() - start_time
        logger.error("", extra={
            "event": "tool_execution_failed",
            "tool_name": name,
            "error": str(e),
            "error_type": type(e).__name__
        })
        return ToolResult(
            success=False,
            tool_name=name,
            error=f"{type(e).__name__}: {e}",
            execution_time=execution_time
        )

    # Validate output
    output_validation = validate_output(output)
    if not output_validation.valid:
        logger.error("", extra={
            "event": "output_validation_failed",
            "tool_name": name,
            "errors": output_validation.errors
        })
        return ToolResult(
            success=False,
            tool_name=name,
            error="; ".join(output_validation.errors),
            validation_errors=output_validation.errors,
            validation_stage="output"
        )

    execution_time = time.time() - start_time

    logger.info("", extra={
        "event": "tool_execution_success",
        "tool_name": name,
        "result": output.value,
        "execution_time": round(execution_time, 6)
    })

    return ToolResult(
        success=True,
        tool_name=name,
        value=output.value,
        execution_time=execution_time
    )

# ============================================================================
# Calculator Tools
# ============================================================================

@tool(input_schema=BinaryOpInput, description="Add two numbers")
def add(input: BinaryOpInput) -> ToolOutput:
    result = input.a + input.b
    return ToolOutput(
        value=result,
        metadata={"operation": "add", "a": input.a, "b": input.b}
    )

@tool(input_schema=BinaryOpInput, description="Subtract b from a")
def subtract(input: BinaryOpInput) -> ToolOutput:
    result = input.a - input.b
    return ToolOutput(
        value=result,
        metadata={"operation": "subtract", "a": input.a, "b": input.b}
    )

@tool(input_schema=BinaryOpInput, description="Multiply two numbers")
def multiply(input: BinaryOpInput) -> ToolOutput:
    result = input.a * input.b
    return ToolOutput(
        value=result,
        metadata={"operation": "multiply", "a": input.a, "b": input.b}
    )

@tool(input_schema=DivideInput, description="Divide a by b")
def divide(input: DivideInput) -> ToolOutput:
    result = input.a / input.b
    return ToolOutput(
        value=result,
        metadata={"operation": "divide", "a": input.a, "b": input.b}
    )

@tool(input_schema=PowerInput, description="Raise base to exponent")
def power(input: PowerInput) -> ToolOutput:
    result = input.base ** input.exponent
    return ToolOutput(
        value=result,
        metadata={"operation": "power", "base": input.base, "exponent": input.exponent}
    )

@tool(input_schema=SqrtInput, description="Calculate square root")
def sqrt(input: SqrtInput) -> ToolOutput:
    result = input.x ** 0.5
    return ToolOutput(
        value=result,
        metadata={"operation": "sqrt", "x": input.x}
    )

# ============================================================================
# REPL
# ============================================================================

def print_help():
    """Print available tools."""
    print("\nAvailable tools:")
    for tool_name in sorted(_REGISTRY.keys()):
        description = _METADATA[tool_name]["description"]
        schema = _INPUT_SCHEMAS[tool_name]
        params = [f.name for f in fields(schema)]
        print(f"  {tool_name}({', '.join(params)}) - {description}")
    print()

def repl():
    """Run the calculator REPL."""
    print("Validated Calculator Agent v2.0")
    print("Type 'help' for available tools, 'quit' to exit")
    print("Input format: TOOL_NAME {\"param\": value, ...}\n")

    while True:
        try:
            line = input("> ").strip()

            if not line:
                continue

            if line == "quit":
                print("Goodbye!")
                break

            if line == "help":
                print_help()
                continue

            # Parse command: tool_name {json}
            parts = line.split(None, 1)
            if len(parts) != 2:
                print("Error: Format is TOOL_NAME {\"param\": value}")
                continue

            tool_name = parts[0]
            json_str = parts[1]

            # Parse JSON
            try:
                input_data = json.loads(json_str)
            except json.JSONDecodeError as e:
                print(f"Error: Invalid JSON: {e}")
                continue

            # Execute tool
            result = call_tool(tool_name, input_data)

            if result.success:
                print(f"Result: {result.value}")
                print(f"Executed in {result.execution_time:.6f}s")
            else:
                if result.validation_stage:
                    print(f"Validation Error ({result.validation_stage}): {result.error}")
                else:
                    print(f"Error: {result.error}")

        except KeyboardInterrupt:
            print("\nGoodbye!")
            break
        except EOFError:
            print("\nGoodbye!")
            break

# ============================================================================
# Main
# ============================================================================

if __name__ == "__main__":
    # Disable JSON logging for cleaner REPL
    logger.disabled = True

    repl()
```

