## Exercise 1: Unit Testing a Tool

```python
import pytest
from calculator import calculator

def test_addition():
    result = calculator({"operation": "add", "a": 2, "b": 3})
    assert result == {"success": True, "result": 5}

def test_subtraction():
    result = calculator({"operation": "subtract", "a": 10, "b": 4})
    assert result == {"success": True, "result": 6}

def test_multiplication():
    result = calculator({"operation": "multiply", "a": 6, "b": 7})
    assert result == {"success": True, "result": 42}

def test_division():
    result = calculator({"operation": "divide", "a": 10, "b": 2})
    assert result == {"success": True, "result": 5.0}

def test_division_by_zero():
    result = calculator({"operation": "divide", "a": 10, "b": 0})
    assert result["success"] == False
    assert "zero" in result["error"].lower()

def test_unknown_operation():
    result = calculator({"operation": "power", "a": 2, "b": 3})
    assert result["success"] == False
    assert "unknown operation" in result["error"].lower()

def test_missing_arguments():
    result = calculator({"operation": "add"})  # Missing a and b
    assert result["success"] == False

@pytest.mark.parametrize("a,b,expected", [
    (1, 1, 2),
    (0, 0, 0),
    (-5, 3, -2),
    (100, 200, 300),
])
def test_addition_cases(a, b, expected):
    result = calculator({"operation": "add", "a": a, "b": b})
    assert result == {"success": True, "result": expected}
