# validators.py
import os
import re

def validate_path(path: str) -> bool:
    """Validate a file path is safe."""
    # Block parent directory traversal
    if ".." in path:
        return False

    # Block absolute paths outside allowed directory
    if path.startswith("/") and not path.startswith("/tmp/safe/"):
        return False

    return True

def validate_url(url: str) -> bool:
    """Validate a URL is safe."""
    # Block file:// protocol
    if url.startswith("file://"):
        return False

    # Only allow http and https
    if not (url.startswith("http://") or url.startswith("https://")):
        return False

    # Block localhost
    if "localhost" in url or "127.0.0.1" in url:
        return False

    return True

def validate_command(cmd: str, allowlist: list) -> bool:
    """Validate a shell command is in the allowlist."""
    # Extract the base command (first word)
    base_cmd = cmd.strip().split()[0] if cmd.strip() else ""

    return base_cmd in allowlist
```

