"""
Resource budget enforcement for agents.
"""

import time
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import List

from ai_skool.logging_setup import get_logger


logger = get_logger(__name__)


class BudgetExceeded(Exception):
    """Raised when a resource budget is exceeded."""
    pass


class Budget(ABC):
    """Abstract base class for resource budgets."""

    @abstractmethod
    def check(self) -> None:
        """Check if budget is exceeded, raise BudgetExceeded if so."""
        pass

    @abstractmethod
    def remaining(self) -> float:
        """Return remaining budget (0.0 to 1.0)."""
        pass

    @abstractmethod
    def reset(self) -> None:
        """Reset the budget."""
        pass


class TokenBudget(Budget):
    """
    Token budget using simple word count approximation.
    """

    def __init__(self, max_tokens: int):
        """
        Initialize token budget.

        Args:
            max_tokens: Maximum token count
        """
        self.max_tokens = max_tokens
        self.used = 0

    def consume(self, tokens: int) -> None:
        """Consume tokens from budget."""
        self.used += tokens
        logger.debug(f"Token budget: {self.used}/{self.max_tokens}")

    def check(self) -> None:
        """Check if budget exceeded."""
        if self.used > self.max_tokens:
            raise BudgetExceeded(f"Token budget exceeded: {self.used}/{self.max_tokens}")

    def remaining(self) -> float:
        """Return remaining budget as fraction."""
        return max(0.0, 1.0 - (self.used / self.max_tokens))

    def reset(self) -> None:
        """Reset token count."""
        self.used = 0


class TimeBudget(Budget):
    """
    Wall-clock time budget.
    """

    def __init__(self, max_seconds: float):
        """
        Initialize time budget.

        Args:
            max_seconds: Maximum execution time in seconds
        """
        self.max_seconds = max_seconds
        self.start_time: float = 0.0

    def start(self) -> None:
        """Start the timer."""
        self.start_time = time.time()

    def elapsed(self) -> float:
        """Get elapsed time."""
        if self.start_time == 0.0:
            return 0.0
        return time.time() - self.start_time

    def check(self) -> None:
        """Check if budget exceeded."""
        if self.elapsed() > self.max_seconds:
            raise BudgetExceeded(f"Time budget exceeded: {self.elapsed():.2f}s/{self.max_seconds}s")

    def remaining(self) -> float:
        """Return remaining budget as fraction."""
        elapsed = self.elapsed()
        return max(0.0, 1.0 - (elapsed / self.max_seconds))

    def reset(self) -> None:
        """Reset timer."""
        self.start_time = 0.0


class BudgetManager:
    """
    Manages multiple budgets and checks them together.
    """

    def __init__(self, budgets: List[Budget]):
        """
        Initialize budget manager.

        Args:
            budgets: List of budget instances
        """
        self.budgets = budgets

    def check_all(self) -> None:
        """Check all budgets, raise BudgetExceeded if any exceeded."""
        for budget in self.budgets:
            budget.check()

    def remaining_min(self) -> float:
        """Return minimum remaining budget across all budgets."""
        if not self.budgets:
            return 1.0
        return min(b.remaining() for b in self.budgets)

    def reset_all(self) -> None:
        """Reset all budgets."""
        for budget in self.budgets:
            budget.reset()

    def track(self):
        """Context manager for tracking budget during execution."""
        return BudgetContext(self)


class BudgetContext:
    """Context manager for budget tracking."""

    def __init__(self, manager: BudgetManager):
        self.manager = manager

    async def __aenter__(self):
        """Start tracking."""
        for budget in self.manager.budgets:
            if isinstance(budget, TimeBudget):
                budget.start()
        return self.manager

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        """Stop tracking and check budgets."""
        if exc_type is None:
            try:
                self.manager.check_all()
            except BudgetExceeded:
                logger.warning("Budget exceeded during execution")
                raise
        return False

