"""
Schema validation system without external dependencies.
"""

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Union


@dataclass
class FieldDefinition:
    """Definition of a single schema field."""
    name: str
    field_type: type
    required: bool = True
    min_length: Optional[int] = None
    max_length: Optional[int] = None
    min_value: Optional[Union[int, float]] = None
    max_value: Optional[Union[int, float]] = None
    allowed_values: Optional[List[Any]] = None
    nested_schema: Optional["Schema"] = None


@dataclass
class Schema:
    """
    Schema definition for validation.
    """
    fields: List[FieldDefinition] = field(default_factory=list)

    def add_field(
        self,
        name: str,
        field_type: type,
        required: bool = True,
        **constraints
    ) -> "Schema":
        """Add a field to the schema (builder pattern)."""
        field_def = FieldDefinition(name=name, field_type=field_type, required=required, **constraints)
        self.fields.append(field_def)
        return self


@dataclass
class ValidationResult:
    """Result of validation operation."""
    is_valid: bool
    errors: List[str] = field(default_factory=list)
    sanitized_data: Optional[Dict[str, Any]] = None


def validate(data: Dict[str, Any], schema: Schema) -> ValidationResult:
    """
    Validate data against a schema.

    Args:
        data: Dictionary to validate
        schema: Schema definition

    Returns:
        ValidationResult with status and any errors
    """
    errors: List[str] = []
    sanitized: Dict[str, Any] = {}

    # Check required fields
    for field_def in schema.fields:
        field_name = field_def.name

        if field_name not in data:
            if field_def.required:
                errors.append(f"Missing required field: {field_name}")
            continue

        value = data[field_name]

        # Type checking
        if not isinstance(value, field_def.field_type):
            # Special case for numeric types
            if field_def.field_type in (int, float):
                if not isinstance(value, (int, float)):
                    errors.append(f"Field '{field_name}' must be {field_def.field_type.__name__}, got {type(value).__name__}")
                    continue
            else:
                errors.append(f"Field '{field_name}' must be {field_def.field_type.__name__}, got {type(value).__name__}")
                continue

        # String length constraints
        if field_def.field_type == str:
            if field_def.min_length is not None and len(value) < field_def.min_length:
                errors.append(f"Field '{field_name}' must be at least {field_def.min_length} characters")
            if field_def.max_length is not None and len(value) > field_def.max_length:
                errors.append(f"Field '{field_name}' must be at most {field_def.max_length} characters")

        # Numeric constraints
        if field_def.field_type in (int, float):
            if field_def.min_value is not None and value < field_def.min_value:
                errors.append(f"Field '{field_name}' must be >= {field_def.min_value}")
            if field_def.max_value is not None and value > field_def.max_value:
                errors.append(f"Field '{field_name}' must be <= {field_def.max_value}")

        # Allowed values constraint
        if field_def.allowed_values is not None and value not in field_def.allowed_values:
            errors.append(f"Field '{field_name}' must be one of {field_def.allowed_values}")

        # Nested schema validation
        if field_def.nested_schema is not None:
            if not isinstance(value, dict):
                errors.append(f"Field '{field_name}' must be an object for nested validation")
            else:
                nested_result = validate(value, field_def.nested_schema)
                if not nested_result.is_valid:
                    for error in nested_result.errors:
                        errors.append(f"{field_name}.{error}")
                    continue
                value = nested_result.sanitized_data

        sanitized[field_name] = value

    # Check for unexpected fields
    for key in data:
        if not any(f.name == key for f in schema.fields):
            errors.append(f"Unexpected field: {key}")

    return ValidationResult(
        is_valid=len(errors) == 0,
        errors=errors,
        sanitized_data=sanitized if len(errors) == 0 else None,
    )

