def print_assessment(data: dict, indent=0):
    """Pretty-print the assessment."""
    for key, value in data.items():
        if isinstance(value, dict) and "rating" in value:
            stars = "*" * value["rating"] + "." * (5 - value["rating"])
            print(f"{'  ' * indent}{key}: [{stars}] {value['rating']}/5")
            if value["evidence"]:
                print(f"{'  ' * (indent+1)}Evidence: {value['evidence']}")
            if value["next_steps"]:
                print(f"{'  ' * (indent+1)}Next: {value['next_steps']}")
        elif isinstance(value, dict):
            print(f"\n{'  ' * indent}{key.upper().replace('_', ' ')}")
            print_assessment(value, indent + 1)
        elif value:
            print(f"{'  ' * indent}{key}: {value}")

